let view='explore', selected='netflix', tab='overview';
const root=document.querySelector('#workspace');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function citations(ids){return '<div class="source-line">Evidence / '+ids.map(id=>{const s=sources.find(x=>x[0]===id);return `<a href="${s[4]}" target="_blank" rel="noopener noreferrer">${s[1]} · ${s[3]} ↗</a>`}).join('')+'</div>'}
function heading(k,h,p=''){return `<div class="heading"><div><div class="eyebrow">${k}</div><h2>${h}</h2></div><p>${p}</p></div>`}
let saved=[];try{saved=JSON.parse(localStorage.getItem('atlas-shortlist')||'[]');if(!Array.isArray(saved))saved=[]}catch{}
function render(){document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='explore')explore();if(view==='learn')learn();if(view==='compare')compare();if(view==='lab')lab();if(view==='opportunities')opps();if(view==='sources')library();}
function explore(){const c=companies.find(x=>x.id===selected);root.innerHTML=heading('01 / COMPANY EXPLORER','Five platforms. Different decisions.','Select a company, then explore its mechanisms and what could transfer to Chase.')+`<div class="companies">${companies.map(x=>`<button class="company ${x.id===selected?'active':''}" data-company="${x.id}" aria-pressed="${x.id===selected}"><span class="logo" style="color:${x.color}">${x.logo}</span><strong>${x.name}</strong><small>${x.surface}</small></button>`).join('')}</div><div class="tabs" aria-label="Deep-dive sections">${['overview','pipeline','technical','chase lens'].map(x=>`<button data-tab="${x}" class="${tab===x?'active':''}" aria-pressed="${tab===x}">${x==='chase lens'?'Opportunities for Chase':x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div><div class="eyebrow">${c.status}</div>`;
if(tab==='overview')root.innerHTML+=`<div class="heading"><h2>${c.headline}</h2></div><div class="grid"><article class="card"><h3>How it works</h3><p>${c.overview}</p>${c.models.map(m=>`<span class="tag">${m}</span>`).join('')}${citations(c.refs)}</article><article class="card dark"><div class="eyebrow">THE PRODUCT QUESTION</div><h3>What is a good recommendation?</h3><p>${c.objective}</p><small>Ask what the system predicts, what the product measures, and where the two differ.</small></article></div><div class="callout"><b>Evidence boundary.</b> ${c.limits}</div>`;
if(tab==='pipeline')root.innerHTML+=`<div class="heading"><h2>${c.name==='Chase'?'A proposed decision flow':'An explanatory pipeline'}</h2></div><p>Reading aid synthesized from the listed sources; stage boundaries vary by implementation.</p><div class="flow">${c.pipeline.map((s,i)=>`<div><b>0${i+1}</b><strong>${s[0]}</strong><small>${s[1]}</small></div>`).join('')}</div><div class="grid"><div class="card"><h3>Signals in</h3><p>${c.signals}</p></div><div class="card"><h3>Outcome to optimize</h3><p>${c.objective}</p></div></div>${citations(c.refs)}<div class="callout">A general systems lesson: gate validity, candidate coverage, ranking quality, and slate quality need separate diagnostics.</div>`;
if(tab==='technical')root.innerHTML+=`<h2 style="margin-top:20px">Under the hood</h2>${c.technical.map((d,i)=>`<details ${i===0?'open':''}><summary>${d[0]}</summary><p>${d[1]}</p></details>`).join('')}${citations(c.refs)}<div class="callout">${c.limits}</div>`;
if(tab==='chase lens')root.innerHTML+=`<div class="card" style="margin-top:18px"><span class="tag">Proposed transfer · not a Chase production claim</span><h2>Connect the dots</h2><p>${c.transfer}</p><button class="action" data-idea="${c.idea}">Open the experiment brief →</button>${citations(c.refs)}</div><div class="callout"><b>Validate internally:</b> existing model capabilities, feature permissions, rule ownership, reward definition, and experiment feasibility.</div>`;
}
function learn(){root.innerHTML=heading('02 / THE LEARNING PATH','From zero to one to N.','Expand a chapter for the mechanism, PM implication, and a banking example.')+`<div class="callout">These chapters explain general recommendation concepts. Company-specific implementation claims live in the source-linked explorer.</div>`+chapters.map((c,i)=>`<article class="card chapter"><div class="number">${String(i+1).padStart(2,'0')} / ${c[0].toUpperCase()}</div><details ${i===0?'open':''}><summary>${c[1]}</summary><p>${c[2]}</p><h3>The PM implication</h3><p>${c[3]}</p><div class="callout"><b>Illustrative banking example:</b> ${c[4]}</div></details></article>`).join('')+`<article class="card dark"><h3>Make the measurement contract explicit</h3><p>Offline: retrieval recall@K, NDCG@K, probability calibration, coverage, and slice performance. Online: incremental customer value per randomized eligible customer, with opt-outs, complaints, gate violations, and latency as guardrails.</p><p>Choose the outcome window before starting. Estimate sample size from baseline variance, the minimum detectable effect, and the unit of randomization. Preserve assignment across sessions and check sample-ratio mismatch.</p><p>A statistically significant engagement increase is insufficient if customer outcomes deteriorate.</p></article>`;}
function compare(){root.innerHTML=heading('03 / SIDE BY SIDE','Compare the decision, not the brand.','Choose any two platforms. Surface and source date matter.')+`<div class="formrow"><label>First platform<select id="left">${companies.map(c=>`<option value="${c.id}">${c.name}</option>`).join('')}</select></label><label>Second platform<select id="right">${companies.map(c=>`<option value="${c.id}" ${c.id==='spotify'?'selected':''}>${c.name}</option>`).join('')}</select></label></div><div id="comparison"></div>`;document.querySelectorAll('#left,#right').forEach(s=>s.onchange=updateCompare);updateCompare();}
function updateCompare(){const a=companies.find(c=>c.id===document.querySelector('#left').value),b=companies.find(c=>c.id===document.querySelector('#right').value);const fields=[['Surface','surface'],['Published model patterns','models'],['Signals','signals'],['Objective','objective'],['Potential Chase transfer','transfer'],['Evidence limits','limits']];document.querySelector('#comparison').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Decision dimension</th><th>${a.name}</th><th>${b.name}</th></tr></thead><tbody>${fields.map(([name,key])=>`<tr><td>${name}</td><td>${Array.isArray(a[key])?a[key].join(', '):a[key]}</td><td>${Array.isArray(b[key])?b[key].join(', '):b[key]}</td></tr>`).join('')}</tbody></table></div>${citations([...new Set([...a.refs,...b.refs])])}`;}
const offers=[{name:'Market basket',category:'Groceries',p:.84,value:8,uplift:.04,seen:4,eligible:true,expired:false},{name:'Fresh pantry',category:'Groceries',p:.73,value:10,uplift:.13,seen:1,eligible:true,expired:false},{name:'City café',category:'Dining',p:.58,value:5,uplift:.19,seen:0,eligible:true,expired:false},{name:'Weekend escape',category:'Travel',p:.31,value:35,uplift:.16,seen:2,eligible:true,expired:false},{name:'Everyday fuel',category:'Transport',p:.65,value:6,uplift:.02,seen:1,eligible:true,expired:false},{name:'Premium hotel',category:'Travel',p:.91,value:45,uplift:.20,seen:0,eligible:false,expired:false},{name:'Local cinema',category:'Entertainment',p:.52,value:9,uplift:.12,seen:0,eligible:true,expired:true}];
function decide({objective,cap,diverse,explore}){let rows=offers.map((o,i)=>({...o,i,reason:!o.eligible?'Ineligible':o.expired?'Expired':o.seen>=cap?'Frequency cap':null,score:objective==='activation'?o.p:objective==='value'?o.p*o.value:o.uplift*o.value}));let pool=rows.filter(o=>!o.reason).sort((a,b)=>b.score-a.score);const slate=[];for(const o of pool){if(diverse&&slate.some(s=>s.category===o.category))continue;if(slate.length<3)slate.push(o);}if(explore&&pool.length>slate.length){const alternative=[...pool].reverse().find(o=>!slate.includes(o)&&(!diverse||!slate.slice(0,2).some(s=>s.category===o.category)));if(alternative){slate.splice(2,1,alternative);alternative.explored=true;}}rows.forEach(o=>{o.position=slate.indexOf(o)+1;if(!o.reason&&!o.position)o.reason=diverse&&slate.some(s=>s.category===o.category)?'Category diversity / outside top 3':'Outside top 3';});return {rows,slate};}
function lab(){root.innerHTML=heading('04 / INTERACTIVE DECISION LAB','What actually makes the slate?','Adjust the policy. Follow each offer through gates, scores, and final selection.')+`<div class="callout"><b>Synthetic teaching demo.</b> Invented offers and probabilities; no real Chase data or trained model. All gates stay enforced. Scores are illustrative expectations, not financial forecasts.</div><div class="grid"><div class="card"><h3>Design the policy</h3><label>Ranking objective<select id="objective"><option value="activation">Predicted activation probability</option><option value="value">Expected redeemed value (toy proxy)</option><option value="uplift">Incremental redeemed value (toy estimate)</option></select></label><label class="check">Frequency cap: <b id="capValue">3</b> prior impressions<input class="range" id="cap" type="range" min="1" max="6" value="3"></label><label class="check"><input id="diverse" type="checkbox" checked> At most one offer per category</label><label class="check"><input id="exploration" type="checkbox"> Demonstrate one exploratory slot</label><small>Exploration deterministically substitutes one lower-ranked eligible option. It illustrates a policy choice; it is not a trained contextual bandit.</small><p><button id="reset" class="action secondary">Reset policy</button></p></div><div class="card dark"><div class="eyebrow">A PM’S READING GUIDE</div><h3>A great score cannot override a hard gate.</h3><p>Eligibility, expiration, and the configured frequency cap remove candidates first. The selected objective changes ranking. Diversity changes the slate.</p><p id="formula"></p><small>The expected-value proxy assumes activation leads to redemption. A real system should estimate redemption separately. Uplift here is an invented treatment-effect input.</small></div></div><div id="labResult" aria-live="polite"></div>`;for(const id of ['objective','cap','diverse','exploration'])document.getElementById(id).oninput=updateLab;document.querySelector('#reset').onclick=()=>lab();updateLab();}
function updateLab(){const objective=document.querySelector('#objective').value,cap=Number(document.querySelector('#cap').value),diverse=document.querySelector('#diverse').checked,explore=document.querySelector('#exploration').checked;document.querySelector('#capValue').textContent=cap;const {rows,slate}=decide({objective,cap,diverse,explore});document.querySelector('#formula').textContent=objective==='activation'?'Score = P(activation)':objective==='value'?'Score = P(activation) × illustrative cash-back value':'Score = illustrative redemption uplift × cash-back value';document.querySelector('#labResult').innerHTML=`<div class="metrics"><div><b>${offers.length}</b><small>CATALOG CANDIDATES</small></div><div><b>${rows.filter(o=>!['Ineligible','Expired','Frequency cap'].includes(o.reason)).length}</b><small>PASS HARD GATES</small></div><div><b>${slate.length}</b><small>FINAL SLATE</small></div><div><b>${new Set(slate.map(o=>o.category)).size}</b><small>CATEGORIES SHOWN</small></div></div><div class="table-wrap"><table><thead><tr><th>Offer / category</th><th>P(activation)</th><th>Uplift input</th><th>Cash back</th><th>Prior impressions</th><th>Score</th><th>Decision</th></tr></thead><tbody>${rows.sort((a,b)=>(a.position||99)-(b.position||99)||b.score-a.score).map(o=>`<tr class="${!o.position?'row-suppressed':''}"><td>${o.name}<br><small>${o.category}</small></td><td>${(o.p*100).toFixed(0)}%</td><td>${(o.uplift*100).toFixed(0)} pp</td><td>$${o.value}</td><td>${o.seen}</td><td>${o.score.toFixed(2)}</td><td>${o.position?`<strong>#${o.position} · Shown${o.explored?' / exploration':''}</strong>`:o.reason}</td></tr>`).join('')}</tbody></table></div><div class="source-line">Toy probabilities and uplift are fixed so the same policy produces the same result. Actual experimentation requires randomized assignment and uncertainty estimates.</div>`;}
function opps(focus){root.innerHTML=heading('05 / THE CHASE OPPORTUNITY MAP','Borrow a pattern. Test a hypothesis.','A practical sequence: instrument → measure → test a bounded policy → consider more complex models.')+`<div class="callout">All briefs are proposed product hypotheses, not known gaps in Chase’s current engine. Confirm overlap with existing work before prioritizing.</div><div class="formrow"><label>Filter by stage<select id="phase"><option>All stages</option><option>Foundation</option><option>Next experiment</option><option>Advanced</option></select></label><label class="check"><input type="checkbox" id="savedOnly"> Shortlisted only</label><button class="action secondary" id="export">Export shortlist</button></div><div class="opps" id="oppCards"></div>`;document.querySelector('#phase').onchange=renderOppCards;document.querySelector('#savedOnly').onchange=renderOppCards;document.querySelector('#export').onclick=exportNotes;renderOppCards(focus);}
function renderOppCards(focus){const phase=document.querySelector('#phase').value,only=document.querySelector('#savedOnly').checked;const items=opportunities.map((o,i)=>({...o,i})).filter(o=>(phase==='All stages'||o.phase===phase)&&(!only||saved.includes(o.i)));document.querySelector('#oppCards').innerHTML=items.length?items.map(o=>`<article class="card" id="idea-${o.i}"><span class="tag">${o.phase}</span><div class="source-line">${o.pattern}</div><h3>${o.title}</h3><p>${o.why}</p><details ${focus===o.i?'open':''}><summary>Read the experiment brief</summary><h3>Smallest useful build</h3><p>${o.build}</p><h3>Validation design</h3><p>${o.experiment}</p><h3>Success and guardrails</h3><p>${o.metric}</p><h3>Watch for</h3><p>${o.risk}</p></details>${citations(o.refs)}<button class="action ${saved.includes(o.i)?'saved':'secondary'}" data-save="${o.i}">${saved.includes(o.i)?'✓ Shortlisted':'＋ Add to shortlist'}</button></article>`).join(''):'<div class="empty">No briefs match this selection. Choose another stage or add a brief to your shortlist.</div>';if(Number.isInteger(focus))document.querySelector(`#idea-${focus}`)?.scrollIntoView({behavior:'smooth',block:'center'});}
function exportNotes(){const items=opportunities.filter((o,i)=>saved.includes(i));const text='# Recommendation Atlas — Chase opportunity shortlist\n\nPublic-research hypotheses · 6 Oct 2026\n\n'+(items.length?items.map(o=>`## ${o.title}\n\nStage: ${o.phase}\nPattern: ${o.pattern}\n\nWhy: ${o.why}\nBuild: ${o.build}\nExperiment: ${o.experiment}\nMetrics: ${o.metric}\nRisks: ${o.risk}\nSources: ${o.refs.map(id=>sources.find(s=>s[0]===id)[4]).join(', ')}\n`).join('\n'):'No opportunities shortlisted.');const url=URL.createObjectURL(new Blob([text],{type:'text/markdown'}));const a=document.createElement('a');a.href=url;a.download='chase-opportunity-shortlist.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function library(){root.innerHTML=heading('06 / RESEARCH NOTES','Follow the evidence.','15 primary-source references. Reviewed 6 Oct 2026; publication dates are shown separately.')+`<input id="sourceSearch" type="search" placeholder="Search company, topic, or year…" aria-label="Search sources"><div class="callout"><b>How to read this guide.</b> Company descriptions are paraphrased from public engineering, research, and product sources. Pipeline diagrams are explanatory syntheses. General learning content, simulations, and Chase opportunities are educational or proposed. This is a curated starting point, not an exhaustive inventory or a claim about undisclosed production systems.</div><div id="sourceList" class="sources"></div>`;document.querySelector('#sourceSearch').oninput=filterSources;filterSources();}
function filterSources(){const q=document.querySelector('#sourceSearch').value.toLowerCase();const list=sources.filter(s=>s.join(' ').toLowerCase().includes(q));document.querySelector('#sourceList').innerHTML=list.length?list.map(s=>`<article class="card"><span class="tag">${s[1]} · ${s[3]}</span><br><a href="${s[4]}" target="_blank" rel="noopener noreferrer">${s[2]} ↗</a><p>${s[5]}</p></article>`).join(''):'<div class="empty">No sources match your search.</div>';}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){view=b.dataset.view;history.replaceState(null,'','#'+view);render();}if(b.dataset.company){selected=b.dataset.company;explore();}if(b.dataset.tab){tab=b.dataset.tab;explore();}if(b.dataset.idea){view='opportunities';render();renderOppCards(Number(b.dataset.idea));}if(b.dataset.save){const i=Number(b.dataset.save);saved=saved.includes(i)?saved.filter(x=>x!==i):[...saved,i];try{localStorage.setItem('atlas-shortlist',JSON.stringify(saved))}catch{}renderOppCards();}});
function fromHash(){const h=location.hash.slice(1);if(['explore','learn','compare','lab','opportunities','sources'].includes(h))view=h;render();}window.addEventListener('hashchange',fromHash);fromHash();
